before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <string>
#include <variant>
int main() {
    std::variant<int, std::string> message = 7;
    if (const auto* number = std::get_if<int>(&message))
        std::cout << "number " << *number << "\n";
    else std::cout << "text " << std::get<std::string>(message) << "\n";
}
```

